1	    // The Check print scenario (--check-print, --check-print-capture <dir>).
2	    // Included inside class Scenario after the print-issue scenarios, whose
3	    // step runner and slicing helpers it uses.
4	    //
5	    // Three plates, each sliced through the header: one with nothing to flag,
6	    // one whose slice generated support, and one without support whose slab
7	    // is printed in the air. For each it opens the real window and reads the report panel's
8	    // contents, then drives the header's Legend switch, selects a finding, and
9	    // checks the window still closes itself when the slice under it goes
10	    // stale. With a capture directory it also saves the panel as the app
11	    // draws it and the window's own canvas pixels.
12	
13	    CheckPrintDialog* check_print_dialog()
14	    {
15	        for (wxWindow* window : wxTopLevelWindows)
16	            if (auto* dialog = dynamic_cast<CheckPrintDialog*>(window); dialog != nullptr && dialog->IsModal())
17	                return dialog;
18	        return nullptr;
19	    }
20	
21	    // Opens Check print, runs `inspect` inside its modal loop, then closes it
22	    // unless `close` is false (the window is expected to close itself).
23	    void with_check_print(const std::string& label, std::function<void(CheckPrintDialog&)> inspect, bool close = true)
24	    {
25	        m_cp_opened = false;
26	        m_frame->CallAfter([self = shared_from_this(), label, inspect, close] {
27	            CheckPrintDialog* dialog = self->check_print_dialog();
28	            self->check(dialog != nullptr, label + "_window_opens_modal");
29	            if (dialog == nullptr)
30	                return;
31	            self->m_cp_opened = true;
32	            dialog->preview()->get_canvas3d()->render();
33	            inspect(*dialog);
34	            if (close && dialog->IsModal())
35	                dialog->EndModal(wxID_CANCEL);
36	        });
37	        installed_shell()->status_row()->request_action(PrintAction::CheckPrint);
38	    }
39	
40	    static std::string utf8(const wxString& text) { return text.ToUTF8().data(); }
41	
42	    void dump_report(const std::string& label, const CheckPrintReportPanel& panel)
43	    {
44	        std::cerr << "HARNESS CHECKPRINT " << label << " valid=" << panel.view().valid << " sections=" << panel.view().sections.size()
45	                  << " clean=" << panel.view().clean.size() << '\n';
46	        for (const wxString& line : panel.drawn_lines())
47	            std::cerr << "HARNESS CHECKPRINT_LINE " << label << " '" << utf8(line) << "'\n";
48	    }
49	
50	    static bool drew_line(const CheckPrintReportPanel& panel, const wxString& words)
51	    {
52	        for (const wxString& line : panel.drawn_lines())
53	            if (line.Contains(words))
54	                return true;
55	        return false;
56	    }
57	
58	    // The closing line wraps, so it is compared joined back into one string.
59	    static bool drew_closing_line(const CheckPrintReportPanel& panel)
60	    {
61	        const wxString expected = CheckPrintReportPanel::closing_line(panel.view());
62	        wxString       joined;
63	        bool           started = false;
64	        for (const wxString& line : panel.drawn_lines()) {
65	            if (line.StartsWith(expected.BeforeFirst(':')))
66	                started = true;
67	            if (started)
68	                joined += (joined.empty() ? "" : " ") + line;
69	        }
70	        return !expected.empty() && joined == expected;
71	    }
72	
73	    static std::vector<PrintCheck> section_checks(const CheckPrintReportView& view)
74	    {
75	        std::vector<PrintCheck> checks;
76	        for (const CheckSection& section : view.sections)
77	            checks.push_back(section.check);
78	        return checks;
79	    }
80	
81	    static bool same_pixels(const wxBitmap& a, const wxBitmap& b)
82	    {
83	        const wxImage ia = a.ConvertToImage(), ib = b.ConvertToImage();
84	        return ia.GetWidth() == ib.GetWidth() && ia.GetHeight() == ib.GetHeight() &&
85	               std::memcmp(ia.GetData(), ib.GetData(), std::size_t(ia.GetWidth()) * ia.GetHeight() * 3) == 0;
86	    }
87	
88	    void save_bitmap(const wxBitmap& bitmap, const std::string& name)
89	    {
90	        if (m_state->capture_dir.empty())
91	            return;
92	        fs::create_directories(m_state->capture_dir);
93	        const std::string file = (m_state->capture_dir / (name + ".png")).string();
94	        check(bitmap.ConvertToImage().SaveFile(wxString::FromUTF8(file), wxBITMAP_TYPE_PNG), "saved_" + name);
95	        std::cout << "HARNESS ARTIFACT " << name << " " << bitmap.GetWidth() << "x" << bitmap.GetHeight() << std::endl;
96	    }
97	
98	    // The canvas's own pixels after a fresh frame, top row first.
99	    wxImage read_canvas(GLCanvas3D& canvas)
100	    {
101	        canvas.render();
102	        const Size size = canvas.get_canvas_size();
103	        const int  w = size.get_width(), h = size.get_height();
104	        std::vector<unsigned char> pixels(std::size_t(w) * h * 4);
105	        glPixelStorei(GL_PACK_ALIGNMENT, 1);
106	        glReadBuffer(GL_FRONT);
107	        glReadPixels(0, 0, w, h, GL_RGBA, GL_UNSIGNED_BYTE, pixels.data());
108	        wxImage image(w, h);
109	        unsigned char* rgb = image.GetData();
110	        for (int y = 0; y < h; ++y)
111	            for (int x = 0; x < w; ++x) {
112	                const unsigned char* from = &pixels[(std::size_t(h - 1 - y) * w + x) * 4];
113	                unsigned char*       to   = &rgb[(std::size_t(y) * w + x) * 3];
114	                to[0] = from[0]; to[1] = from[1]; to[2] = from[2];
115	            }
116	        return image;
117	    }
118	
119	    // Pixels within a few steps of `colour` inside the rectangle.
120	    static int count_colour(const wxImage& image, const wxRect& rect, const wxColour& colour)
121	    {
122	        int found = 0;
123	        const wxRect inside = rect.Intersect(wxRect(0, 0, image.GetWidth(), image.GetHeight()));
124	        for (int y = inside.y; y < inside.GetBottom(); ++y)
125	            for (int x = inside.x; x < inside.GetRight(); ++x) {
126	                const unsigned char* px = image.GetData() + (std::size_t(y) * image.GetWidth() + x) * 3;
127	                if (std::abs(px[0] - colour.Red()) <= 6 && std::abs(px[1] - colour.Green()) <= 6 && std::abs(px[2] - colour.Blue()) <= 6)
128	                    ++found;
129	            }
130	        return found;
131	    }
132	
133	    // The header's one switch, off when the window opens, driving OrcaSlicer's
134	    // legend and nothing else; the moves slider stays as OrcaSlicer shows it.
135	    void check_legend_switch(CheckPrintDialog& dialog, const std::string& label)
136	    {
137	        check(!dialog.legend_toggle()->is_checked(), label + "_switch_starts_off");
138	        check(!dialog.legend_shown(), label + "_legend_hidden_at_open");
139	        dialog.legend_toggle()->toggle();
140	        check(dialog.legend_toggle()->is_checked() && dialog.legend_shown(), label + "_switch_shows_the_legend");
141	        dialog.legend_toggle()->toggle();
142	        check(!dialog.legend_shown(), label + "_switch_hides_the_legend");
143	    }
144	
145	    // A post with a slab floating 2 mm above it: the slab's first slice has
146	    // nothing under it, which is an unsupported island at a known height.
147	    std::string write_floating_stl()
148	    {
149	        const std::string path = (fs::path(data_dir()) / "check-print-floating.stl").string();
150	        std::ofstream out(path);
151	        out << "solid floating\n";
152	        write_box(out, {-5, -5, 0}, {5, 5, 10});
153	        write_box(out, {-15, -15, 12}, {15, 15, 15});
154	        out << "endsolid floating\n";
155	        return path;
156	    }
157	
158	    // Loads one STL into a new project, centred on the first plate.
159	    void load_centred(const std::string& label, const std::string& stl)
160	    {
161	        answer_modals(wxID_NO);
162	        check(m_plater->new_project(true, true) != wxID_CANCEL, label + "_new_project");
163	        stop_answering_modals();
164	        check(m_plater->load_files(std::vector<std::string>{stl},
165	                  LoadStrategy::LoadModel | LoadStrategy::AddDefaultInstances | LoadStrategy::Silence, false).size() == 1,
166	              label + "_model_loaded");
167	        PartPlateList& plates = m_plater->get_partplate_list();
168	        check(plates.get_plate(0)->add_instance(0, 0, true) == 0, label + "_model_centred");
169	        m_plater->canvas3D()->reload_scene(true, true);
170	    }
171	
172	    // A key as the window's char hook sees it, before the focused control.
173	    static void press(wxWindow& target, int key, bool shift = false, wxEventType type = wxEVT_CHAR_HOOK)
174	    {
175	        wxKeyEvent event(type);
176	        event.m_keyCode = key;
177	        event.SetShiftDown(shift);
178	        event.SetEventObject(&target);
179	        target.ProcessWindowEvent(event);
180	    }
181	
182	    void self_check_focus(wxWindow* expected, const std::string& name)
183	    {
184	        wxWindow* focused = wxWindow::FindFocus();
185	        std::cerr << "HARNESS CHECKPRINT focus " << name << " is='" << (focused ? utf8(focused->GetName()) : std::string("none")) << "'\n";
186	        check(focused == expected, name);
187	    }
188	
189	    // The Tab order, walked forwards from the canvas and back again. The order
190	    // itself is always checked; the focus actually moving is checked only when
191	    // macOS gives this app keyboard focus, which it does not while another app
192	    // is in front.
193	    void check_tab_order(CheckPrintDialog& dialog, const std::string& label)
194	    {
195	        const std::vector<wxWindow*> order = dialog.focus_order();
196	        bool forward = true, backward = true;
197	        for (std::size_t index = 0; index < order.size(); ++index) {
198	            forward  = forward && dialog.next_focus(order[index], false) == order[(index + 1) % order.size()];
199	            backward = backward && dialog.next_focus(order[index], true) == order[(index + order.size() - 1) % order.size()];
200	        }
201	        check(order.size() == 4 && order[1] == dialog.report() && order[2] == dialog.legend_toggle() &&
202	                  order[3] == static_cast<wxWindow*>(dialog.close_button()),
203	              label + "_tab_order_is_canvas_report_legend_close");
204	        check(forward, label + "_tab_order_wraps_forwards");
205	        check(backward, label + "_tab_order_wraps_backwards");
206	
207	        order[0]->SetFocus();
208	        if (wxWindow::FindFocus() != order[0]) {
209	            std::cerr << "HARNESS CHECKPRINT focus UNOBSERVED: the app does not hold keyboard focus\n";
210	            return;
211	        }
212	        SimpleEvent canvas_tab(EVT_GLCANVAS_TAB);
213	        order[0]->ProcessWindowEvent(canvas_tab);
214	        self_check_focus(order[1], label + "_canvas_tab_moves_to_the_report");
215	        order[0]->SetFocus();
216	        bool moved = true;
217	        for (std::size_t step = 1; step <= order.size(); ++step) {
218	            press(dialog, WXK_TAB);
219	            moved = moved && wxWindow::FindFocus() == order[step % order.size()];
220	        }
221	        for (std::size_t step = 1; step <= order.size(); ++step) {
222	            press(dialog, WXK_TAB, true);
223	            moved = moved && wxWindow::FindFocus() == order[(order.size() - step) % order.size()];
224	        }
225	        check(moved, label + "_tab_and_shift_tab_move_the_focus");
226	    }
227	
228	    void begin_check_print()
229	    {
230	        auto  self  = shared_from_this();
231	        auto& steps = m_issue_steps;
232	
233	        // ---- A. Nothing to flag: one cube, no support --------------------------------------
234	        steps.push_back({"cp_a_plain_cube", [self] {
235	            self->two_cubes("cp_a");
236	            self->m_plater->remove(1);
237	            self->set_process_option("enable_support", new ConfigOptionBool(false));
238	            self->set_process_option("brim_type", new ConfigOptionEnum<BrimType>(btNoBrim));
239	        }, {}, {}});
240	        steps.push_back({"cp_a_slice", [self] { self->slice_now(); }, self->slice_ended(), [self] {
241	            self->stop_answering_modals();
242	            // Prepare's view zoomed in, as a person leaves it; the window
243	            // must open on the whole slice anyway and give this view back.
244	            self->m_plater->get_camera().set_zoom(self->m_plater->get_camera().get_zoom() * 6);
245	            Camera before = self->m_plater->get_camera();
246	            // OrcaSlicer's G-code listing preference on, its default.
247	            if (!wxGetApp().show_gcode_window())
248	                wxGetApp().toggle_show_gcode_window();
249	            // The pointer last seen on Prepare's canvas, where this window's
250	            // layer slider will be.
251	            ImGui::GetIO().MousePos = ImVec2(self->prepare_canvas().get_canvas_size().get_width() - 40.f, 120.f);
252	            self->with_check_print("cp_a", [self, &before](CheckPrintDialog& dialog) {
253	                CheckPrintReportPanel& panel  = *dialog.report();
254	                GLCanvas3D&            canvas = *dialog.preview()->get_canvas3d();
255	                const ShellMetrics&    m      = brand_theme()->metrics();
256	                self->check(canvas.legacy_overlays_hidden(), "cp_a_plate_strip_navigator_and_toolbar_hidden");
257	                self->check(!wxGetApp().show_gcode_window(), "cp_a_gcode_listing_off_at_open");
258	                self->check(ImGui::GetIO().MousePos.x < -1e30f && ImGui::GetCurrentContext()->HoveredWindow == nullptr,
259	                            "cp_a_no_hover_without_a_pointer");
260	                canvas.render();
261	                const Vec3d fitted = canvas.get_gcode_viewer().get_paths_bounding_box().center();
262	                std::cerr << "HARNESS CHECKPRINT camera target=" << self->m_plater->get_camera().get_target().transpose()
263	                          << " paths_centre=" << fitted.transpose() << '\n';
264	                self->check((self->m_plater->get_camera().get_target() - fitted).norm() < 0.01, "cp_a_opens_fitted_to_the_slice");
265	                self->check(dialog.GetMinClientSize() == dialog.FromDIP(wxSize(900, 600)), "cp_a_window_has_a_minimum_size");
266	                self->check_tab_order(dialog, "cp_a");
267	                // The quiet Close button takes the header's raised surface, in dark too.
268	                HeaderButton& close = *dialog.close_button();
269	                close.set_dark(true);
270	                const wxImage close_dark = close.snapshot().ConvertToImage();
271	                close.set_dark(GUI_App::dark_mode());
272	                const wxColour raised = brand_theme()->palette(true).surface_raised;
273	                self->check(close_dark.GetRed(1, 1) == raised.Red() && close_dark.GetGreen(1, 1) == raised.Green() &&
